package e.e.a;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.*;import android.os.Build;import android.view.*;import android.widget.*;
/** Shared theme context for generated windows; media and web pixels are never recolored. */
public final class UiTheme191 {
 private UiTheme191(){}
 public static Context context(Context source){Context owner=UiDialogs.owner(source);String name=ThemeChoice.isAmoled(owner)?"NicoidDialogAMOLED":ThemeChoice.isNight(owner)?"NicoidDialogDark":"NicoidDialogLight";int style=owner.getResources().getIdentifier(name,"style",owner.getPackageName());return new ContextThemeWrapper(owner,style!=0?style:ThemeChoice.isNight(owner)?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert);}
 public static void window(Dialog dialog){if(dialog.getWindow()==null)return;Context c=dialog.getContext();GradientDrawable bg=PanelUi.round(c,UiDialogs.surface(c),24);dialog.getWindow().setBackgroundDrawable(bg);surface(dialog.getWindow().getDecorView());ThemeChoice.controls(dialog.getWindow().getDecorView());FlatUi191.window(dialog);}
 static boolean media(View v){String name=v.getClass().getName();return v instanceof ImageView||v instanceof SurfaceView||v instanceof TextureView||v instanceof android.webkit.WebView||name.startsWith("com.devbrackets.")||name.contains("PlayerView");}
 static boolean light(int color){return Color.alpha(color)>245&&Math.min(Color.red(color),Math.min(Color.green(color),Color.blue(color)))>205;}
 public static void surface(View view){if(view==null||media(view))return;boolean dark=ThemeChoice.isNight(view.getContext());if(dark){Drawable bg=view.getBackground();if(bg instanceof ColorDrawable&&light(((ColorDrawable)bg).getColor()))view.setBackgroundColor(UiDialogs.surface(view.getContext()));else if(Build.VERSION.SDK_INT>=24&&bg instanceof GradientDrawable){android.content.res.ColorStateList colors=((GradientDrawable)bg).getColor();if(colors!=null&&light(colors.getDefaultColor()))((GradientDrawable)bg.mutate()).setColor(UiDialogs.surface(view.getContext()));}if(view instanceof TextView){TextView text=(TextView)view;int ink=text.getCurrentTextColor();if(Color.alpha(ink)>240&&Math.max(Color.red(ink),Math.max(Color.green(ink),Color.blue(ink)))<130)text.setTextColor(DialogColors.INK_DARK);}}ThemeChoice.controlsOne(view);if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int n=0;n<g.getChildCount();n++)surface(g.getChildAt(n));}}
 public static void activity(Activity a){for(String name:new String[]{"left_drawer","menu_listview","videoinfotitlelay","videomenulist","infoscroll"}){int id=a.getResources().getIdentifier(name,"id",a.getPackageName());View view=id==0?null:a.findViewById(id);if(view!=null){ThemeChoice.background(view);surface(view);}}}
}
